import { useState, useEffect, useCallback } from "react";

import { DocumentLookupResult, IComponent, StudioProApi } from "@mendix/extensions-api";
import { ConsumedMCPService } from "../../types/consumedMCPService";
import { createNewConsumedMCPService } from "../../utils/consumedMCPServiceUtils";
import { handleConsumedMCPServiceChangeValue } from "./consumedMCPServiceHandlers";

import { PageContainer, ContentColumn, PageContent } from "../components/PageContainers";

import AppThemeProvider from "../components/AppThemeProvider";
import FormDivider from "../components/FormDivider"
import TextInputLabeled from "../components/TextInputLabeled";
import { createDocumentEditorComponent } from "../utils/componentLoader";

const initialConsumedMCPService: ConsumedMCPService = createNewConsumedMCPService()

interface AppProps {
    studioPro: StudioProApi;
    documentId: string;
}
const App: React.FC<AppProps> = ({ studioPro, documentId }) => {
    const messageBoxApi = studioPro.ui.messageBoxes;
    const documentApi = studioPro.app.model.customBlobDocuments;
    const [documentVersion, setDocumentVersion] = useState(0);
    const [isLoaded, setIsLoaded] = useState(false);
    const [consumedMCPService, setConsumedMCPService] = useState(initialConsumedMCPService);
    
    //will be needed later
    const createChangeValueHandler = useCallback((fieldName: keyof ConsumedMCPService) =>
        handleConsumedMCPServiceChangeValue(studioPro, fieldName, consumedMCPService, setConsumedMCPService, documentId),
        [studioPro, consumedMCPService, setConsumedMCPService, documentId]
    );

    useEffect(() => {
        const handleDocumentsChanged = (event: { documents: Array<{ id: string }> }) => {
            const { documents } = event;
            if (documents.some(doc => doc.id === documentId)) {
                setDocumentVersion(v => v + 1);
            }
        };
        documentApi.addEventListener("documentsChanged", handleDocumentsChanged);
        return () => {
            documentApi.removeEventListener("documentsChanged", handleDocumentsChanged);
        };
    }, []);


    useEffect(() => {
        documentApi
            .getDocumentById<ConsumedMCPService>(documentId)
            .then(async (documentFromModel: DocumentLookupResult<ConsumedMCPService>) => {
                if (documentFromModel && !("error" in documentFromModel)) {
                    const consumedMCPService: ConsumedMCPService = documentFromModel.document.contents;
                    const consumedMCPServiceName: string = documentFromModel.document.name;
                    setConsumedMCPService({ ...consumedMCPService, name: consumedMCPServiceName });
                    setIsLoaded(true);
                } else {
                    throw new Error(documentFromModel?.error || "Document not found");
                }
            })
            .catch(err => {
                messageBoxApi.show("error", "Error loading document", "Details: " + err?.message || err);
            });
    }, [documentVersion]);

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainer>
                {!isLoaded && <span>Loading document content...</span>}
                {isLoaded && <PageContent>
                    <ContentColumn>
                        <FormDivider label="General">
                            <TextInputLabeled
                                label="Name"
                                ariaLabel="Name"
                                value={consumedMCPService.name}
                                onChange={() => { }}
                                readOnly
                            />
                        </FormDivider>
                    </ContentColumn>
                </PageContent>}
            </PageContainer>
        </AppThemeProvider>
    );
};

export const component: IComponent = createDocumentEditorComponent(App);